"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { Avatar } from "./avatar";
import { toSquareDataUrl } from "../lib/image";

export interface AvatarUploadProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "onError"> {
  /** Huidige foto als URL of data-URL. */
  value?: string | null;
  /** Naam voor de initialen wanneer er geen foto is. */
  name?: string;
  size?: number;
  /** Krijgt de nieuwe data-URL, of null bij verwijderen. */
  onChange?: (dataUrl: string | null) => void;
  onError?: (message: string) => void;
  /** Zijde van de bewaarde afbeelding in pixels. */
  outputSize?: number;
  disabled?: boolean;
  /** Knoppen naast de avatar tonen. */
  showActions?: boolean;
  addLabel?: string;
  changeLabel?: string;
  removeLabel?: string;
}

/**
 * AvatarUpload — avatar met camerabadge en bestandskiezer. De afbeelding wordt
 * in de browser bijgesneden en verkleind, dus je bewaart een compacte data-URL.
 */
export const AvatarUpload = React.forwardRef<HTMLDivElement, AvatarUploadProps>(
  function AvatarUpload(
    {
      value,
      name = "",
      size = 64,
      onChange,
      onError,
      outputSize = 160,
      disabled,
      showActions = true,
      addLabel = "Foto toevoegen",
      changeLabel = "Foto wijzigen",
      removeLabel = "Verwijderen",
      className,
      ...rest
    },
    ref
  ) {
    const input = React.useRef<HTMLInputElement>(null);

    const pick = () => {
      if (!disabled) input.current?.click();
    };

    const handle = async (file?: File | null) => {
      if (!file) return;
      try {
        onChange?.(await toSquareDataUrl(file, { size: outputSize }));
      } catch (error) {
        onError?.(error instanceof Error ? error.message : "Uploaden mislukt");
      }
    };

    return (
      <div ref={ref} className={cn("lui-avatar-upload", className)} {...rest}>
        <button
          type="button"
          className="lui-avatar-upload-btn"
          onClick={pick}
          disabled={disabled}
          aria-label={value ? changeLabel : addLabel}
          title={value ? changeLabel : addLabel}
        >
          <Avatar name={name} src={value ?? undefined} size={size} />
          <span className="lui-avatar-upload-badge" style={{ width: size * 0.34, height: size * 0.34 }}>
            <Icon name="camera" size={Math.max(11, size * 0.18)} />
          </span>
        </button>

        <input
          ref={input}
          type="file"
          accept="image/*"
          className="lui-sr-only"
          disabled={disabled}
          onChange={(event) => {
            const file = event.target.files?.[0];
            event.target.value = "";
            void handle(file);
          }}
        />

        {showActions && (
          <div className="lui-avatar-upload-actions">
            <button type="button" className="lui-avatar-upload-action" onClick={pick} disabled={disabled}>
              <Icon name="camera" size={14} />
              {value ? changeLabel : addLabel}
            </button>
            {value && (
              <button
                type="button"
                className="lui-avatar-upload-action lui-avatar-upload-remove"
                onClick={() => onChange?.(null)}
                disabled={disabled}
              >
                <Icon name="trash" size={14} />
                {removeLabel}
              </button>
            )}
          </div>
        )}
      </div>
    );
  }
);

/* ============================ AvatarUpload ============================ */
.lui-avatar-upload { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }

.lui-avatar-upload-btn {
  position: relative; display: inline-flex; padding: 0;
  border: none; background: transparent; cursor: pointer; border-radius: var(--r-full);
}
.lui-avatar-upload-btn:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-avatar-upload-btn:disabled { cursor: not-allowed; opacity: .6; }

.lui-avatar-upload-badge {
  position: absolute; right: -2px; bottom: -2px;
  display: grid; place-items: center;
  border-radius: var(--r-full);
  background: var(--accent); color: var(--accent-fg);
  border: 2px solid var(--surface);
  transition: background var(--dur-fast);
}
.lui-avatar-upload-btn:hover .lui-avatar-upload-badge { background: var(--accent-hover); }

.lui-avatar-upload-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.lui-avatar-upload-action {
  display: inline-flex; align-items: center; gap: 7px;
  height: calc(32px * var(--density)); padding: 0 12px;
  border: 1px solid var(--border); border-radius: var(--r-sm);
  background: var(--surface); color: var(--text-2);
  font: inherit; font-size: 12.5px; font-weight: 600; cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast);
}
.lui-avatar-upload-action:hover:not(:disabled) { background: var(--surface-hover); color: var(--text); }
.lui-avatar-upload-action:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-avatar-upload-action:disabled { opacity: .5; cursor: not-allowed; }
.lui-avatar-upload-remove { color: var(--red); border-color: var(--red-border); }
.lui-avatar-upload-remove:hover:not(:disabled) { background: var(--red-tint); color: var(--red); }

/**
 * Kleine beeldhulp — verkleint een gekozen afbeelding tot een vierkante
 * data-URL. Gebruikt alleen canvas: geen upload, geen bibliotheek.
 */

export interface SquareImageOptions {
  /** Zijde van het resultaat in pixels. */
  size?: number;
  /** JPEG-kwaliteit tussen 0 en 1. */
  quality?: number;
  type?: "image/jpeg" | "image/png" | "image/webp";
}

/** Snijdt het midden uit een afbeelding en schaalt naar een vierkante data-URL. */
export function toSquareDataUrl(file: File, options: SquareImageOptions = {}): Promise<string> {
  const { size = 160, quality = 0.82, type = "image/jpeg" } = options;

  return new Promise((resolve, reject) => {
    if (!file || !/^image\//.test(file.type)) {
      reject(new Error("Geen afbeelding"));
      return;
    }

    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Bestand kon niet gelezen worden"));
    reader.onload = () => {
      const image = new Image();
      image.onerror = () => reject(new Error("Afbeelding kon niet geladen worden"));
      image.onload = () => {
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const context = canvas.getContext("2d");
        if (!context) {
          reject(new Error("Canvas niet beschikbaar"));
          return;
        }
        const scale = Math.max(size / image.width, size / image.height);
        const width = image.width * scale;
        const height = image.height * scale;
        context.drawImage(image, (size - width) / 2, (size - height) / 2, width, height);
        resolve(canvas.toDataURL(type, quality));
      };
      image.src = String(reader.result);
    };
    reader.readAsDataURL(file);
  });
}
